9	}
10	int sc_main(int argc,char **argv) {
11	 GlobalParams::buffer_depth=8;GlobalParams::n_virtual_channels=2;GlobalParams::verbose_mode="OFF";
12	 ProcessingElement p("receiver");p.local_id=0;p.role=ROLE_GLB;p.compute_cycles=0;p.outputs_received_count_=0;
13	 for(auto &b:p.rx_buffer)b.SetMaxBufferSize(8);
14	 const std::string scenario=argc>1?argv[1]:"shared_committed";
15	 if(scenario=="independent" || scenario=="independent_same") {p.role=ROLE_BUFFER;p.unified_buffer_manager_=new BufferManager(std::map<DataType,size_t>{{DataType::INPUT,64},{DataType::WEIGHT,64},{DataType::OUTPUT,64}});}
16	 else p.unified_buffer_manager_=new BufferManager(96);
17	 bool ok=false;
18	 if(scenario=="sanity") {
19	  head(p,0,DataType::INPUT,32);p.internal_transfer_process();tail(p,0,DataType::INPUT,32);p.internal_transfer_process();
20	  ok=p.rx_buffer[0].IsEmpty()&&p.unified_buffer_manager_->GetCurrentSize(DataType::INPUT)==32&&p.main_receiving_size_==0;
21	 } else if(scenario=="direct_committed" || scenario=="direct_reserved") {
22	  if(scenario=="direct_committed") p.unified_buffer_manager_->OnDataReceived(DataType::INPUT,64);
23	  else {head(p,0,DataType::INPUT,64);p.internal_transfer_process();}
24	  Packet pkt{};pkt.data_type=DataType::WEIGHT;pkt.payload_data_size=64;pkt.command=0;pkt.logical_timestamp=0;
25	  const bool advertised=p.can_accept_direct_packet(pkt);const bool accepted=p.receive_direct_packet(pkt,1);
26	  std::cout<<"direct advertised="<<advertised<<" accepted="<<accepted<<" WEIGHT committed="<<p.unified_buffer_manager_->GetCurrentSize(DataType::WEIGHT)<<"\n";
27	  ok=!advertised&&!accepted;
28	 } else if(scenario=="shared_committed") {
29	  p.unified_buffer_manager_->OnDataReceived(DataType::INPUT,64);
30	  head(p,0,DataType::WEIGHT,64);p.internal_transfer_process();
31	  const bool blocked=!p.rx_buffer[0].IsEmpty();
32	  std::cout<<"HEAD blocked="<<blocked<<" committed="<<p.unified_buffer_manager_->GetCurrentSize()<<"\n";
33	  if(!blocked){tail(p,0,DataType::WEIGHT,64);p.internal_transfer_process();std::cout<<"TAIL consumed="<<p.rx_buffer[0].IsEmpty()<<" WEIGHT committed="<<p.unified_buffer_manager_->GetCurrentSize(DataType::WEIGHT)<<"\n";}
34	  else {p.unified_buffer_manager_->RemoveData(DataType::INPUT,64);p.internal_transfer_process();tail(p,0,DataType::WEIGHT,64);p.internal_transfer_process();}
35	  ok=blocked&&p.unified_buffer_manager_->GetCurrentSize(DataType::WEIGHT)==64;
36	 } else {
37	  head(p,0,DataType::INPUT,64);p.internal_transfer_process();
38	  const DataType second=scenario=="independent"?DataType::WEIGHT:scenario=="independent_same"?DataType::INPUT:DataType::OUTPUT;
39	  head(p,1,second,64);p.internal_transfer_process();
40	  const bool blocked=!p.rx_buffer[1].IsEmpty();
41	  std::cout<<"second HEAD blocked="<<blocked<<" INPUT reservation="<<p.main_receiving_size_<<" OUTPUT reservation="<<p.output_receiving_size_<<"\n";
42	  ok=scenario=="independent"?!blocked:blocked;
43	 }
44	 std::cout<<(ok?"PASS ":"FAIL ")<<scenario<<"\n";return ok?0:1;
45	}
