30	void ProcessingElement::configure(int id, int level_idx,
31	                                  const HierarchicalConfig &topology_config)
32	{
33	  //========================================================================
34	  // I. 保存基础信息
35	  //========================================================================
36	  this->local_id = id;
37	  this->level_index = level_idx;
38	  if (GlobalParams::pe_registry.size() <= static_cast<size_t>(local_id))
39	  {
40	    GlobalParams::pe_registry.resize(local_id + 1, nullptr);
41	  }
42	  GlobalParams::pe_registry[local_id] = this;
43	
44	  //========================================================================
45	  // II. 根据层级确定角色和基础配置
46	  //========================================================================
47	  assert(level_idx < topology_config.levels.size());
48	  const LevelConfig &level_config = topology_config.get_level_config(level_idx);
49	
50	  // 设置角色（假设每层只有一个主要角色）
51	  this->role = level_config.roles;
52	
53	  // 设置缓冲区容量
54	  this->max_capacity = level_config.buffer_size[0];
55	
56	  //========================================================================
57	  // III. 配置上游/下游连接
58	  //========================================================================
59	  // 清空现有连接
60	  this->upstream_node_ids.clear();
61	  this->downstream_node_ids.clear();
62	
63	  // 配置上游
64	  int parent_id = GlobalParams::parent_map[this->local_id];
65	  if (parent_id != -1)
66	  {
67	    this->upstream_node_ids.push_back(parent_id);
68	  }
69	
70	  // 配置下游
71	  int num_children = GlobalParams::fanouts_per_level[level_idx];
72	  int *children = GlobalParams::child_map[this->local_id];
73	  for (int i = 0; i < num_children; i++)
74	  {
75	    this->downstream_node_ids.push_back(children[i]);
76	  }
77	
78	  //========================================================================
79	  // IV. 执行角色专属的初始化
80	  //========================================================================
81	  switch (this->role)
82	  {
83	  case ROLE_DRAM:
84	  {
85	    // 共享模式
86	    unified_buffer_manager_ = new BufferManager(max_capacity);
87	
88	    // 配置TaskManager
89	    task_manager_ = std::unique_ptr<TaskManager>(new TaskManager());
90	    task_manager_->Configure(GlobalParams::workload, "ROLE_DRAM");
91	    auto dataset = task_manager_->get_current_working_set();
92	    if (dataset.inputs >= 0 && dataset.weights >= 0)
93	    {
94	      unified_buffer_manager_->OnDataReceived(DataType::INPUT, dataset.inputs);
95	      unified_buffer_manager_->OnDataReceived(DataType::WEIGHT,
96	                                              dataset.weights);
97	    }
98	
99	    if (dataset.outputs >= 0)
100	    {
101	      unified_buffer_manager_->OnDataReceived(DataType::OUTPUT,
102	                                              dataset.outputs);
103	    }
104	
105	    // 使用配置的outputs_required_count值
106	    auto *role_working_set =
107	        task_manager_->get_working_set_for_role("ROLE_DRAM");
108	    outputs_required_count_ = role_working_set->outputs_required_count;
109	    outputs_received_count_ = 0;
110	
111	    // 状态初始化
112	    dispatch_in_progress_ = false;
113	    logical_timestamp = 0;
114	    break;
115	  }
116	
117	  case ROLE_GLB:
118	  {
119	    // 共享模式
120	    unified_buffer_manager_ = new BufferManager(max_capacity);
121	    current_data_size.write(unified_buffer_manager_->GetCurrentSize());
122	
123	    // 配置TaskManager
124	    task_manager_ = std::unique_ptr<TaskManager>(new TaskManager());
125	    task_manager_->Configure(GlobalParams::workload, "ROLE_GLB");
126	    // 使用配置的outputs_required_count值
127	    auto *role_working_set =
128	        task_manager_->get_working_set_for_role("ROLE_GLB");
129	    outputs_required_count_ = role_working_set->outputs_required_count;
130	    outputs_received_count_ = 0;
131	
132	    this->downstream_node_ids.clear();
133	    for (auto compute_node :
134	         GlobalParams::storage_to_compute_map[this->local_id])
135	    {
136	      this->downstream_node_ids.push_back(compute_node);
137	    }
138	
139	    break;
140	  }
141	
142	  case ROLE_BUFFER:
143	  {
144	    // 独立模式
145	    std::map<DataType, size_t> type_caps;
146	    type_caps[DataType::WEIGHT] = level_config.buffer_size[0];
147	    type_caps[DataType::INPUT] = level_config.buffer_size[1];
148	    type_caps[DataType::OUTPUT] = level_config.buffer_size[2];
149	    unified_buffer_manager_ = new BufferManager(type_caps);
150	
151	    current_data_size.write(unified_buffer_manager_->GetCurrentSize());
152	
153	    // 配置TaskManager
154	    task_manager_ = std::unique_ptr<TaskManager>(new TaskManager());
155	    task_manager_->Configure(GlobalParams::workload, "ROLE_BUFFER");
156	
157	    // 从配置中读取自驱逐参数
158	    const RoleProperties *props =
159	        task_manager_->get_properties_for_role("ROLE_BUFFER");
160	    if (props)
161	    {
162	      eviction_interval_cycles_ = props->eviction_interval_cycles;
163	      weight_eviction_amount_ = props->weight_eviction_amount;
164	      weight_multiplier_ = props->weight_multiplier;
165	    }
166	    else
167	    {
168	      eviction_interval_cycles_ = 0; // 默认值：不启用自驱逐
169	      weight_eviction_amount_ = 0;   // 默认值：不驱逐权重
170	      weight_multiplier_ = 0;        // 默认值：不启用动态倍数
171	    }
172	
173	    // 使用配置的outputs_required_count值
174	    auto *role_working_set =
175	        task_manager_->get_working_set_for_role("ROLE_BUFFER");
176	    outputs_required_count_ = role_working_set->outputs_required_count;
177	    outputs_received_count_ = 0;
178	    compute_cycles = 0;
179	
180	    this->upstream_node_ids.clear();
181	    this->upstream_node_ids.push_back(
182	        GlobalParams::compute_to_storage_map[this->local_id]);
183	
184	    break;
185	  }
186	
187	  case ROLE_DISTRIBUTOR:
188	  {
189	    break;
190	  }
191	
192	  default:
193	    // 未处理的角色类型
194	    assert(false && "Unknown PE_Role in configure function");
195	    break;
196	  }
197	
198	  //========================================================================
199	  // V. 通用状态初始化
200	  //========================================================================
201	  logical_timestamp = 0;
202	  init_return_credit_constants();
203	
204	  // 调试日志
205	  LOG << "PE[" << local_id << "] configured as " << role_to_str(role)
206	      << " at level " << level_idx << endl;
207	}
