218	void ProcessingElement::rxProcess()
219	{
220	  // --- 0. 复位逻辑 ---
221	  if (reset.read())
222	  {
223	    // 重置接收状态计数器
224	    main_receiving_size_ = 0;
225	    output_receiving_size_ = 0;
226	
227	    for (int i = 0; i < NUM_LOCAL_PORTS; ++i)
228	    {
229	      ack_rx[i].write(0);
230	      current_level_rx[i] = 0;
231	
232	      // 重置 buffer_full_status_rx 输出端口（表示所有VC都未满）
233	      TBufferFullStatus reset_status;
234	      for (int vc = 0; vc < MAX_VIRTUAL_CHANNELS; ++vc)
235	      {
236	        reset_status.mask[vc] = false; // false 表示未满
237	      }
238	      buffer_full_status_rx[i].write(reset_status);
239	    }
240	
241	    // 清空所有缓冲区
242	    rx_buffer.fill(Buffer()); // 重新构造所有Buffer
243	    for (int vc = 0; vc < GlobalParams::n_virtual_channels; vc++)
244	    {
245	      rx_buffer[vc].SetMaxBufferSize(GlobalParams::buffer_depth);
246	      rx_buffer[vc].setLabel(string(name()) + "->buffer[0]");
247	    }
248	    return;
249	  }
250	
251	  if (role == ROLE_DISTRIBUTOR)
252	    return;
253	
254	  // ==========================================================
255	  // 阶段一: [核心] 调用内部处理函数
256	  // ==========================================================
257	  // 在接收任何新 Flit 之前，首先尝试处理掉物理缓冲区中已有的 Flit
258	  internal_transfer_process();
259	
260	  // ==========================================================
261	  // 阶段二: 接收新的入站 Flit
262	  // ==========================================================
263	  // 这部分是物理接收逻辑，负责将新来的 Flit Push 进 rx_buffer
264	  for (int i = 0; i < NUM_LOCAL_PORTS; ++i)
265	  {
266	    if (i == 0)
267	    {
268	      // --- Port 0: 新的支持VC的缓冲逻辑 ---
269	
270	      // 物理握手：检查是否有新的请求req_rx[port_index].read() == 1 -
271	      // current_level
272	      if (req_rx[0].read() == 1 - current_level_rx[0])
273	      {
274	
275	        // 读取 Flit
276	        Flit flit = flit_rx[0].read();
277	
278	        // 获取 VC ID
279	        int vc_id = flit.vc_id;
280	
281	        // 检查 VC ID 是否有效
282	        if (vc_id >= 0 && vc_id < MAX_VIRTUAL_CHANNELS)
283	        {
284	
285	          // 推入 BufferBank 中对应的 VC 缓冲区
286	          // 使用断言确保缓冲区未满（通过流控机制保证）
287	          assert(!rx_buffer[vc_id].IsFull() &&
288	                 "VC buffer should not be full due to backpressure");
289	
290	          rx_buffer[vc_id].Push(flit);
291	
292	          // 确认握手：翻转 current_level 并写入 ack_rx
293	          current_level_rx[0] = 1 - current_level_rx[0];
294	          ack_rx[0].write(current_level_rx[0]);
295	
296	          // 调试日志
297	          LOG << "@" << sc_time_stamp() << " [" << name() << "]: "
298	              << "[RX_PORT0] Received Flit on VC " << vc_id
299	              << " src_id=" << flit.src_id << " dst_id=" << flit.dst_id
300	              << " flit_type=" << flit.flit_type
301	              << " buffer_size=" << rx_buffer[vc_id].Size()
302	              << " flit_data_type=" << DataType_to_str(flit.data_type)
303	              << " flit_seq_no=" << flit.sequence_no
304	              << " flit_command=" << flit.command << std::endl
305	              << " target_role=" << role_to_str(flit.target_role);
306	        }
307	        else
308	        {
309	          // 无效的 VC ID - 这是编程错误，应该使用断言
310	          assert(false && "Invalid VC ID received");
311	        }
312	      }
313	    }
314	    else if (i == 1)
315	    {
316	      // --- Port 1: 暂时保留旧逻辑或占位符 ---
317	      // TODO: 为 port 1 实现新的缓冲逻辑
318	
319	      // 暂时保留旧的调用（标记为待删除）
320	      // handle_rx_for_port(1);
321	
322	      // 或者暂时留空
323	    }
324	  }
325	
326	  // ==========================================================
327	  // 阶段三: 更新对上游的流控信号
328	  // ==========================================================
329	  // 这个逻辑报告的是物理缓冲区 rx_buffer 的状态
330	  for (int i = 0; i < NUM_LOCAL_PORTS; ++i)
331	  {
332	    TBufferFullStatus status;
333	
334	    if (i == 0)
335	    {
336	      // Port 0: 检查每个 VC 的缓冲区状态
337	      for (int vc = 0; vc < MAX_VIRTUAL_CHANNELS; ++vc)
338	      {
339	        status.mask[vc] = rx_buffer[vc].IsFull(); // true 表示已满
340	      }
341	    }
342	    else
343	    {
344	      // Port 1: 暂时返回默认状态（所有VC都未满）
345	      for (int vc = 0; vc < MAX_VIRTUAL_CHANNELS; ++vc)
346	      {
347	        status.mask[vc] = false; // false 表示未满
348	      }
349	    }
350	
351	    // 写入流控状态输出端口
352	    buffer_full_status_rx[i].write(status);
353	  }
354	}
