356	// 新增：内部流式处理函数实现
357	void ProcessingElement::internal_transfer_process()
358	{
359	  // 遍历所有虚拟通道
360	  for (int vc = 0; vc < GlobalParams::n_virtual_channels; ++vc)
361	  {
362	    Buffer &vc_buffer = rx_buffer[vc];
363	
364	    // 流式处理循环：处理该VC中所有可以处理的Flit
365	    while (!vc_buffer.IsEmpty())
366	    {
367	      // 窥视队首Flit
368	      const Flit &flit = vc_buffer.Front();
369	
370	      if (flit.flit_type == FLIT_TYPE_HEAD)
371	      {
372	        // [特殊处理] 如果是回传包 (command == -1)，跳过流控检查
373	        if (flit.command == -1)
374	        {
375	          // 回传包无条件接受（假设已预留空间）
376	          vc_buffer.Pop();
377	
378	          LOG << "[INTERNAL_TRANSFER] Accepted OUTPUT_RETURN HEAD Flit on VC "
379	              << " cycle= " << compute_cycles << vc << " src_id=" << flit.src_id
380	              << " payload=" << flit.payload_data_size
381	              << " command_id=" << flit.command << endl;
382	          continue; // 继续处理下一个flit
383	        }
384	
385	        // 正常数据包的流控检查
386	        size_t *receiving_size = nullptr;
387	
388	        if (flit.data_type == DataType::OUTPUT)
389	        {
390	          receiving_size = &output_receiving_size_;
391	        }
392	        else
393	        {
394	          receiving_size = &main_receiving_size_;
395	        }
396	
397	        // 执行关键的流控决策
398	        size_t required_capacity =
399	            unified_buffer_manager_->GetCurrentSize(flit.data_type) +
400	            *receiving_size + flit.payload_data_size;
401	
402	        if (required_capacity <=
403	            unified_buffer_manager_->GetCapacity(flit.data_type))
404	        {
405	          // 检查通过：预留空间
406	          *receiving_size += flit.payload_data_size;
407	          vc_buffer.Pop();
408	
409	          // 处理command_id等元数据
410	          if (flit.command != -1 &&
411	              flit.data_type != DataType::WEIGHT)
412	          { // need fix
413	            pending_commands_[flit.logical_timestamp] = flit.command;
414	          }
415	
416	          LOG << "[INTERNAL_TRANSFER] Accepted HEAD Flit on VC " << vc
417	              << " src_id=" << flit.src_id
418	              << " payload=" << flit.payload_data_size
419	              << " reserved_space=" << *receiving_size
420	              << " command_id=" << flit.command << endl;
421	        }
422	        else
423	        {
424	          // 逻辑缓冲区空间不足，阻塞当前VC
425	          LOG << "[INTERNAL_TRANSFER] HEAD Flit BLOCKED on VC " << vc
426	              << " required=" << required_capacity << " capacity="
427	              << unified_buffer_manager_->GetCapacity(flit.data_type) << endl;
428	          break;
429	        }
430	      }
431	      else if (flit.flit_type == FLIT_TYPE_BODY)
432	      {
433	        // BODY Flit无条件丢弃
434	        vc_buffer.Pop();
435	        LOG << "[INTERNAL_TRANSFER] Processed OUTPUT_RETURN body Flit on VC "
436	            << vc << " src_id=" << flit.src_id
437	            << " payload=" << flit.payload_data_size
438	            << "seq_no=" << flit.sequence_no << endl;
439	      }
440	      else if (flit.flit_type == FLIT_TYPE_TAIL)
441	      {
442	        // [核心修改] 特殊处理回传包
443	        if (flit.command == -1)
444	        {
445	          // 这是一个输出回传包，只更新计数器，不调用BufferManager
446	          outputs_received_count_ += flit.payload_data_size;
447	          // assert(outputs_received_count_ <= outputs_required_count_ &&
448	          //        "Received more outputs than required");
449	
450	          vc_buffer.Pop();
451	
452	          cout << "sc_timestamp = " << sc_time_stamp()
453	               << " cycle= " << current_cycle
454	               << "[INTERNAL_TRANSFER] Processed OUTPUT_RETURN TAIL Flit on VC "
455	               << vc << " src_id=" << flit.src_id
456	               << " payload=" << flit.payload_data_size
457	               << " total_outputs_received=" << outputs_received_count_ << "/"
458	               << outputs_required_count_ << endl;
459	
460	          // 通知可能等待输出的逻辑
461	          buffer_state_changed_event.notify(SC_ZERO_TIME);
462	          continue;
463	        }
464	
465	        // 正常数据包的TAIL处理
466	        size_t *receiving_size = nullptr;
467	
468	        if (flit.data_type == DataType::OUTPUT)
469	        {
470	          receiving_size = &output_receiving_size_;
471	        }
472	        else
473	        {
474	          receiving_size = &main_receiving_size_;
475	        }
476	
477	        // 调用OnDataReceived将数据正式"入库"
478	        unified_buffer_manager_->OnDataReceived(flit.data_type,
479	                                                flit.payload_data_size);
480	        // 释放预留的空间
481	        assert(*receiving_size >= flit.payload_data_size &&
482	               "Receiving size underflow");
483	        *receiving_size -= flit.payload_data_size;
484	
485	        vc_buffer.Pop();
486	
487	        // 通知计算逻辑
488	        buffer_state_changed_event.notify(SC_ZERO_TIME);
489	
490	        LOG << "[RECEIVE_EVENT] Processed TAIL Flit on VC " << vc
491	            << " src_id=" << flit.src_id
492	            << " type=" << DataType_to_str(flit.data_type)
493	            << " payload=" << flit.payload_data_size
494	            << " committed_to_logic_buffer"
495	            << "buffer_size="
496	            << unified_buffer_manager_->GetCurrentSize(flit.data_type) << "/"
497	            << unified_buffer_manager_->GetCapacity(flit.data_type) << endl;
498	      }
499	    }
500	  }
501	}
502	// 新增：统一的VC发送处理函数实现
503	void ProcessingElement::handle_tx_for_all_vcs()
504	{
505	  // [核心] 遍历所有 VC 发送队列
506	  for (int i = 0; i < GlobalParams::n_virtual_channels; ++i)
507	  {
508	    int vc = (last_serviced_vc_ + 1 + i) % GlobalParams::n_virtual_channels;
509	    // 如果这个 VC 的队列里没有包，跳过
510	    if (packet_queues_[vc].empty())
511	    {
512	      continue;
513	    }
514	
515	    // 检查当前端口是否正在等待ACK（简化模型：假设统一使用port 0）
516	
517	    // "窥视"队首的包
518	    Packet &packet_to_send = packet_queues_[vc].front();
519	
520	    // Ideal mode: bypass flits/links/routers and directly deliver packet
521	    // payload to destination PE accounting.
522	    if (GlobalParams::ideal_transport &&
523	        GlobalParams::ideal_return_accounting &&
524	        packet_to_send.command == -1 && role != ROLE_DISTRIBUTOR)
525	    {
526	      if (!direct_deliver_return_credit(packet_to_send))
527	      {
528	        LOG << "[TX_VC" << vc
529	            << "] Direct-return blocked "
530	            << "target_role=" << role_to_str(packet_to_send.target_role)
531	            << " payload=" << packet_to_send.payload_data_size
532	            << " src=" << local_id << endl;
533	        continue;
534	      }
535	
536	      packet_queues_[vc].pop();
537	      last_serviced_vc_ = vc;
538	      LOG << "[TX_VC" << vc << "] Direct-return credited "
539	          << "src=" << packet_to_send.src_id
540	          << " payload=" << packet_to_send.payload_data_size << endl;
541	      break;
542	    }
543	
544	    // Hybrid ideal mode:
545	    // - Non-return packets: direct packet-level delivery (bypass NoC links)
546	    // - Return packets: optionally bypassed by direct return accounting branch
547	    if (GlobalParams::ideal_transport && packet_to_send.command != -1)
548	    {
549	      if (!direct_deliver_packet(packet_to_send))
550	      {
551	        LOG << "[TX_VC" << vc
552	            << "] Direct-deliver blocked "
553	            << "cmd=" << packet_to_send.command
554	            << " target_role=" << role_to_str(packet_to_send.target_role)
555	            << " payload=" << packet_to_send.payload_data_size << endl;
556	        continue;
557	      }
558	
559	      packet_queues_[vc].pop();
560	      last_serviced_vc_ = vc;
561	      LOG << "[TX_VC" << vc << "] Direct-delivered packet "
562	          << "src=" << packet_to_send.src_id
563	          << " payload=" << packet_to_send.payload_data_size
564	          << " type=" << DataType_to_str(packet_to_send.data_type)
565	          << " command_id=" << packet_to_send.command << endl;
566	      break;
567	    }
568	
569	    // Physical flit path still requires ABP handshake readiness.
570	    if (ack_tx[0].read() != current_level_tx[0])
571	    {
572	      continue;
573	    }
574	
575	    // 检查下游邻居的 VC 流控状态
576	    TBufferFullStatus downstream_status = buffer_full_status_tx[0].read();
577	
578	    if (downstream_status.mask[vc] == true || packet_queues_[vc].empty())
579	    {
580	      // 这个 VC 被阻塞了，跳过，去处理下一个 VC
581	      continue;
582	    }
583	
584	    // --- 流控检查通过！可以发送 ---
585	
586	    Flit flit_to_send = generate_next_flit_from_queue(packet_queues_[vc]);
587	
588	    // 设置VC ID
589	    flit_to_send.vc_id = vc;
590	    last_serviced_vc_ = vc;
591	
592	    // 物理发送 (统一到 Port 0)
593	    flit_tx[0].write(flit_to_send);
594	    current_level_tx[0] = 1 - current_level_tx[0];
595	    req_tx[0].write(current_level_tx[0]);
596	
597	    // 打印发送日志
598	    LOG << "[TX_VC" << vc << "] Sent Flit type=" << flit_to_send.flit_type
599	        << " src=" << flit_to_send.src_id << " dst=" << flit_to_send.dst_id
600	        << " command_id=" << flit_to_send.command << endl;
601	
602	    // 如果发送的是 TAIL Flit，从这个 VC 的队列中 pop
603	    if (flit_to_send.flit_type == FLIT_TYPE_TAIL)
604	    {
605	      // packet_queues_[vc].pop();
606	      LOG << "[TX_VC" << vc << "] Completed packet transmission" << endl;
607	    }
608	
609	    // 既然我们每周期只发送一个 Flit，就在成功发送后退出循环
610	    break;
611	  }
612	}
