627	int ProcessingElement::resolve_return_target_node(const Packet &pkt) const
628	{
629	  if (pkt.dst_id >= 0)
630	  {
631	    return pkt.dst_id;
632	  }
633	
634	  int parent_id = GlobalParams::parent_map[local_id];
635	  while (parent_id != -1)
636	  {
637	    if (parent_id >= 0 &&
638	        parent_id < static_cast<int>(GlobalParams::pe_registry.size()))
639	    {
640	      ProcessingElement *pe = GlobalParams::pe_registry[parent_id];
641	      if (pe != nullptr && pe->role == pkt.target_role)
642	      {
643	        return parent_id;
644	      }
645	    }
646	    parent_id = GlobalParams::parent_map[parent_id];
647	  }
648	
649	  if (!upstream_node_ids.empty())
650	  {
651	    return upstream_node_ids[0];
652	  }
653	
654	  return -1;
655	}
