657	size_t ProcessingElement::compute_return_credit_for_target(const Packet &pkt,
658	                                                           int target_id) const
659	{
660	  size_t multiplier = 1;
661	  int cur = GlobalParams::parent_map[local_id];
662	
663	  while (cur != -1)
664	  {
665	    const int lvl = GlobalParams::node_level_map[cur];
666	    const LevelConfig &level_cfg =
667	        GlobalParams::hierarchical_config.get_level_config(lvl);
668	
669	    if (level_cfg.aggregate)
670	    {
671	      size_t factor = 1;
672	      auto it = level_cfg.routing_patterns.find(DataType::OUTPUT);
673	      if (it != level_cfg.routing_patterns.end() &&
674	          !it->second.port_groups.empty())
675	      {
676	        factor = it->second.port_groups.size();
677	      }
678	      else if (GlobalParams::fanouts_per_level[lvl] > 0)
679	      {
680	        factor = static_cast<size_t>(GlobalParams::fanouts_per_level[lvl]);
681	      }
682	      multiplier *= factor;
683	    }
684	
685	    if (cur == target_id)
686	    {
687	      return static_cast<size_t>(pkt.payload_data_size) * multiplier;
688	    }
689	
690	    cur = GlobalParams::parent_map[cur];
691	  }
692	
693	  return 0;
694	}
