696	bool ProcessingElement::receive_direct_return_credit(size_t credited_outputs,
697	                                                     int src_id,
698	                                                     int source_compute_cycle)
699	{
700	  (void)credited_outputs;
701	  std::set<int> &seen =
702	      return_sources_seen_by_compute_cycle_[source_compute_cycle];
703	  if (seen.count(src_id) != 0)
704	  {
705	    LOG << "[DIRECT_RETURN] Duplicate source ignored "
706	        << "cycle=" << source_compute_cycle << " src=" << src_id
707	        << " dst=" << local_id << endl;
708	    return true;
709	  }
710	  seen.insert(src_id);
711	  pending_return_outputs_by_compute_cycle_[source_compute_cycle] += credited_outputs;
712	
713	  const size_t expected_sources =
714	      expected_return_sources_cached_ > 0 ? expected_return_sources_cached_
715	                                          : get_expected_return_source_count();
716	  if (expected_sources == 0)
717	  {
718	    LOG << "[DIRECT_RETURN] Invalid expected source count (0) for dst="
719	        << local_id << endl;
720	    return false;
721	  }
722	
723	  if (seen.size() < expected_sources)
724	  {
725	    LOG << "[DIRECT_RETURN] Buffered "
726	        << "cycle=" << source_compute_cycle << " src=" << src_id
727	        << " dst=" << local_id << " progress=" << seen.size() << "/"
728	        << expected_sources
729	        << " pending_outputs="
730	        << pending_return_outputs_by_compute_cycle_[source_compute_cycle]
731	        << endl;
732	    return true;
733	  }
734	
735	  const size_t observed_batch =
736	      pending_return_outputs_by_compute_cycle_[source_compute_cycle];
737	  const size_t credited_batch =
738	      return_credit_batch_cached_ > 0 ? return_credit_batch_cached_
739	                                      : observed_batch;
740	  outputs_received_count_ += credited_batch;
741	  pending_return_outputs_by_compute_cycle_.erase(source_compute_cycle);
742	  return_sources_seen_by_compute_cycle_.erase(source_compute_cycle);
743	  buffer_state_changed_event.notify(SC_ZERO_TIME);
744	
745	  cout << "sc_timestamp = " << sc_time_stamp() << " [DIRECT_RETURN] Credited "
746	       << "cycle=" << source_compute_cycle << " src=" << src_id
747	       << " dst=" << local_id << " credited_batch=" << credited_batch
748	       << " observed_batch=" << observed_batch
749	       << " total_outputs_received=" << outputs_received_count_ << "/"
750	       << outputs_required_count_ << endl;
751	  return true;
752	}
