767	size_t ProcessingElement::compute_return_multiplier_from_source_role(
768	    PE_Role source_role) const
769	{
770	  int source_level = -1;
771	  for (size_t i = 0; i < GlobalParams::hierarchical_config.levels.size(); ++i)
772	  {
773	    if (GlobalParams::hierarchical_config.levels[i].roles == source_role)
774	    {
775	      source_level = static_cast<int>(i);
776	      break;
777	    }
778	  }
779	  if (source_level <= level_index)
780	  {
781	    return 1;
782	  }
783	
784	  size_t multiplier = 1;
785	  for (int lvl = source_level - 1; lvl >= level_index; --lvl)
786	  {
787	    const LevelConfig &level_cfg =
788	        GlobalParams::hierarchical_config.get_level_config(lvl);
789	    if (!level_cfg.aggregate)
790	    {
791	      continue;
792	    }
793	    size_t factor = 1;
794	    auto it = level_cfg.routing_patterns.find(DataType::OUTPUT);
795	    if (it != level_cfg.routing_patterns.end() && !it->second.port_groups.empty())
796	    {
797	      factor = it->second.port_groups.size();
798	    }
799	    else if (GlobalParams::fanouts_per_level[lvl] > 0)
800	    {
801	      factor = static_cast<size_t>(GlobalParams::fanouts_per_level[lvl]);
802	    }
803	    multiplier *= factor;
804	  }
805	  return multiplier;
806	}
