808	void ProcessingElement::init_return_credit_constants()
809	{
810	  expected_return_sources_cached_ = get_expected_return_source_count();
811	  return_credit_per_src_cached_ = 0;
812	  return_credit_batch_cached_ = 0;
813	
814	  if (task_manager_ == nullptr || expected_return_sources_cached_ == 0)
815	  {
816	    return;
817	  }
818	
819	  const PE_Role source_role =
820	      static_cast<PE_Role>(static_cast<int>(role) + 1);
821	  auto *commands = task_manager_->get_commands_for_role(role_to_str(source_role));
822	  if (commands == nullptr || commands->empty())
823	  {
824	    return;
825	  }
826	
827	  size_t source_outputs = 0;
828	  for (const auto &cmd : *commands)
829	  {
830	    if (cmd.evict_payload.outputs > 0)
831	    {
832	      source_outputs = static_cast<size_t>(cmd.evict_payload.outputs);
833	      break;
834	    }
835	  }
836	  if (source_outputs == 0)
837	  {
838	    return;
839	  }
840	
841	  // In ideal return accounting, per-source credit represents one logical
842	  // producer's completion signal (e.g., 16 outputs), not the aggregated payload.
843	  return_credit_per_src_cached_ = source_outputs;
844	
845	  // Batch credit is the logical per-round contribution at this destination.
846	  // Keep aggregation multiplier, but do not multiply by source count again.
847	  const size_t multiplier =
848	      compute_return_multiplier_from_source_role(source_role);
849	  return_credit_batch_cached_ = source_outputs * multiplier;
850	}
