962	
963	bool ProcessingElement::direct_deliver_packet(const Packet &pkt)
964	{
965	  vector<int> targets;
966	
967	  // Keep parity with Router::route() semantics in hierarchical mode:
968	  // command == -1 packets always move one hop UP until they reach target role.
969	  if (pkt.command == -1)
970	  {
971	    targets = upstream_node_ids;
972	  }
973	  else if (pkt.dst_id >= 0)
974	  {
975	    targets.push_back(pkt.dst_id);
976	  }
977	  else
978	  {
979	    // Role-based direct delivery: resolve all nodes matching target_role.
980	    for (size_t i = 0; i < GlobalParams::pe_registry.size(); ++i)
981	    {
982	      ProcessingElement *cand = GlobalParams::pe_registry[i];
983	      if (cand != nullptr && cand->role == pkt.target_role)
984	      {
985	        targets.push_back(static_cast<int>(i));
986	      }
987	    }
988	
989	    // Fallback to local topology hints if role-based lookup returns empty.
990	    if (targets.empty())
991	    {
992	      if (pkt.target_role == ROLE_GLB)
993	      {
994	        targets = upstream_node_ids;
995	      }
996	      else if (pkt.target_role == ROLE_BUFFER ||
997	               pkt.target_role == ROLE_DISTRIBUTOR)
998	      {
999	        targets = downstream_node_ids;
1000	      }
1001	    }
1002	  }
1003	
1004	  if (targets.empty())
1005	  {
1006	    LOG << "[DIRECT] No targets resolved for packet: target_role="
1007	        << role_to_str(pkt.target_role) << " dst_id=" << pkt.dst_id
1008	        << " command=" << pkt.command << endl;
1009	    return false;
1010	  }
1011	
1012	  // Pre-check all targets first to avoid partial commit.
1013	  for (int dst_id : targets)
1014	  {
1015	    if (dst_id < 0 ||
1016	        dst_id >= static_cast<int>(GlobalParams::pe_registry.size()))
1017	    {
1018	      LOG << "[DIRECT] Invalid dst_id=" << dst_id
1019	          << " registry_size=" << GlobalParams::pe_registry.size() << endl;
1020	      return false;
1021	    }
1022	    ProcessingElement *dst = GlobalParams::pe_registry[dst_id];
1023	    if (dst == nullptr)
1024	    {
1025	      LOG << "[DIRECT] Null dst PE pointer for dst_id=" << dst_id << endl;
1026	      return false;
1027	    }
1028	    if (!dst->can_accept_direct_packet(pkt))
1029	    {
1030	      LOG << "[DIRECT] Dst cannot accept packet. dst_id=" << dst_id
1031	          << " dst_role=" << role_to_str(dst->role)
1032	          << " data_type=" << DataType_to_str(pkt.data_type)
1033	          << " payload=" << pkt.payload_data_size
1034	          << " command=" << pkt.command << endl;
1035	      return false;
1036	    }
1037	  }
1038	
1039	  for (int dst_id : targets)
1040	  {
1041	    ProcessingElement *dst = GlobalParams::pe_registry[dst_id];
1042	    if (!dst->receive_direct_packet(pkt, local_id))
1043	    {
1044	      return false;
1045	    }
1046	  }
1047	
1048	  return true;
1049	}
1050	
1051	void ProcessingElement::txProcess()
1052	{
1053	  // 复位逻辑保持不变（更新以清空新的VC队列）
1054	  if (reset.read())
1055	  {
1056	    req_tx[0].write(0);
1057	    current_level_tx[0] = 0;
1058	    compute_in_progress_ = false;
1059	    is_compute_complete = false;
1060	    compute_cycles = 0;
1061	    last_serviced_vc_ = -1;
1062	
1063	    // 清空所有VC队列
1064	    for (auto &q : packet_queues_)
1065	    {
1066	      while (!q.empty())
1067	        q.pop();
1068	    }
1069	    return;
1070	  }
1071	
1072	  if (role == ROLE_DISTRIBUTOR)
1073	    return;
1074	
1075	  // --- 步骤 A: 如果需要，智能地生成Packet ---
1076	  // 只有在所有VC队列为空时，才尝试生成新的Packet
1077	  // 根据角色调用生成逻辑。
1078	  // run_storage_logic 内部已经包含了所有"意图"和"能力"的匹配检查。
1079	  // 如果条件不满足，它什么也不会做，VC队列依然为空。
1080	  if (role == ROLE_DRAM || role == ROLE_GLB)
1081	  {
1082	    run_storage_logic();
1083	  }
1084	
1085	  else if (role == ROLE_BUFFER)
1086	  {
1087	    run_compute_logic();
1088	  }
1089	
1090	  // --- 步骤 B: [核心替换] 调用新的统一发送处理器 ---
1091	  handle_tx_for_all_vcs();
1092	
1093	  // 计算当前需要的输出数量
1094	  size_t required_outputs = outputs_required_count_;
1095	
1096	  // 如果是最后一个时间步且是同步点，需要2倍输出（补偿第一个未同步的债务）
1097	  if (static_cast<size_t>(logical_timestamp) ==
1098	          task_manager_->get_total_timesteps() - 1 &&
1099	      task_manager_->is_in_sync_points(logical_timestamp))
1100	  {
1101	    required_outputs *= 2;
1102	  }
1103	
1104	  // 同步检查：有sync_point的节点
1105	  if (role != ROLE_BUFFER &&
1106	      task_manager_->is_in_sync_points(logical_timestamp) &&
1107	      outputs_received_count_ < required_outputs)
1108	  {
1109	    return; // 阻塞时间步递增
1110	  }
1111	
1112	  // 所有节点（包括无sync_point的节点）在最后一个时间步检查输出是否满足
1113	  if (role != ROLE_BUFFER &&
1114	      static_cast<size_t>(logical_timestamp) ==
1115	          task_manager_->get_total_timesteps() - 1 &&
1116	      outputs_received_count_ < outputs_required_count_)
1117	  {
1118	    return; // 阻塞时间步递增
1119	  }
1120	
1121	  if (role != ROLE_BUFFER && current_dispatch_task_.sub_tasks.empty() &&
1122	      packet_queues_are_empty() && dispatch_in_progress_)
1123	  {
1124	    if (task_manager_->is_in_sync_points(logical_timestamp))
1125	    {
1126	      // 最后一个同步点重置双倍计数
1127	      if (static_cast<size_t>(logical_timestamp) ==
1128	          task_manager_->get_total_timesteps() - 1)
1129	      {
1130	        outputs_received_count_ -= outputs_required_count_ * 2;
1131	      }
1132	      else
1133	      {
1134	        outputs_received_count_ -= outputs_required_count_;
1135	      }
1136	    }
1137	    logical_timestamp++;
1138	    dispatch_in_progress_ = false;
1139	    if (role == ROLE_DRAM)
1140	      cout << sc_time_stamp() << ": PE[" << local_id
1141	           << "] Completed dispatch for timestamp " << logical_timestamp - 1
1142	           << endl;
1143	    if (logical_timestamp >= task_manager_->get_total_timesteps())
1144	    {
1145	      reset_logic();
1146	    }
1147	  }
1148	
1149	  if (role == ROLE_BUFFER && is_compute_complete == true)
1150	  {
1151	    logical_timestamp++;
1152	    is_compute_complete = false;
1153	    compute_cycles++;
1154	
1155	    // 基于计算周期数判断是否需要自驱逐
1156	    if (eviction_interval_cycles_ > 0 && compute_cycles > 0 &&
1157	        compute_cycles % eviction_interval_cycles_ == 0)
1158	    {
1159	      evict_weights_self();
1160	    }
1161	    if (logical_timestamp >= task_manager_->get_total_timesteps())
1162	    {
1163	      reset_logic();
1164	    }
1165	  }
1166	}
1167	
1168	void ProcessingElement::reset_logic()
1169	{
1170	  if (role == ROLE_DRAM)
1171	  {
1172	    dbg(sc_time_stamp(), "All tasks completed quiting simulation");
1173	    sc_stop();
1174	    return;
1175	  }
1176	
1177	  if ((role == ROLE_GLB || role == ROLE_BUFFER) && !pending_commands_.empty())
1178	  {
1179	
1180	    auto it = pending_commands_.begin();
1181	    int command = it->second;
1182	    pending_commands_.erase(it);
1183	    DataDelta cmd;
1184	    if (command >= task_manager_->get_command_count())
1185	    {
1186	      cmd = task_manager_->get_current_working_set();
1187	      if (eviction_interval_cycles_ > 0)
1188	        cmd.weights = 0;
1189	    }
1190	    else
1191	    {
1192	      cmd = task_manager_->get_command_definition(command);
1193	    }
1194	    unified_buffer_manager_->RemoveData(DataType::WEIGHT, cmd.weights);
1195	    unified_buffer_manager_->RemoveData(DataType::INPUT, cmd.inputs);
1196	    if (cmd.outputs > 0)
1197	    {
1198	      Packet pkt;
1199	      pkt.src_id = local_id;
1200	      pkt.dst_id = -2;
1201	      pkt.payload_data_size = cmd.outputs;
1202	      pkt.data_type = DataType::OUTPUT;
1203	      int bandwidth_scale =
1204	          GlobalParams::hierarchical_config.get_level_config(level_index - 1)
1205	              .bandwidth /
1206	          GlobalParams::word_bits;
1207	      pkt.size = pkt.flit_left =
1208	          (cmd.outputs + bandwidth_scale - 1) / bandwidth_scale + 2;
1209	      pkt.command = -1; // 表示这是一个回送包
1210	      pkt.vc_id = 2;    // 回送包使用vc 0
1211	
1212	      pkt.target_role = static_cast<PE_Role>(static_cast<int>(role) - 1);
1213	      // dbg(sc_time_stamp(), name(), "[RESET_LOGIC] Generating output return
1214	      // Packet to PE " + std::to_string(pkt.dst_id) +
1215	      //     " for " + std::to_string(cmd.outputs) + " bytes.");
1216	      LOG << "[RESET_LOGIC] Generating output return Packet to PE "
1217	          << pkt.target_role << " for " << cmd.outputs << " bytes." << endl;
1218	
1219	      packet_queues_[pkt.vc_id].push(pkt);
1220	    }
1221	    unified_buffer_manager_->RemoveData(DataType::OUTPUT, cmd.outputs);
1222	
1223	    LOG << sc_time_stamp() << ": PE[" << local_id << "]"
1224	        << " Resetting for timestamp " << it->first << " "
1225	        << unified_buffer_manager_->GetCurrentSize() << "/"
1226	        << unified_buffer_manager_->GetCapacity()
1227	        << " bytes remaining after resetting for timestamp "
1228	        << logical_timestamp << endl;
1229	    output_buffer_state_changed_event.notify();
1230	  }
1231	
1232	  logical_timestamp = 0;
1233	  outputs_received_count_ = 0;
1234	  return_sources_seen_by_compute_cycle_.clear();
1235	  pending_return_outputs_by_compute_cycle_.clear();
1236	  current_cycle++;
1237	}
1238	
1239	void ProcessingElement::run_compute_logic()
1240	{
1241	  if (role != ROLE_BUFFER)
1242	  {
1243	    return;
1244	  }
1245	
1246	  bool started_this_cycle = false;
1247	
1248	  if (!compute_in_progress_)
1249	  {
1250	    // 4. Dependency Check: Verify that all required data for the *current*
1251	    // timestep's computation is present. A compute task's dependencies are
1252	    // its required Inputs and Weights.
1253	    const auto &required_data =
1254	        task_manager_->get_working_set_for_role(role_to_str(role))
1255	            ->get_data_map();
1256	
1257	    // 新增：收集所有缺失的数据类型
1258	    std::vector<DataType> missing_types;
1259	
1260	    // 检查所有数据类型
1261	    for (const auto &entry : required_data)
1262	    {
1263	      DataType type = entry.first;
1264	      size_t size = entry.second;
1265	      if (type == DataType::WEIGHT && weight_multiplier_ > 0)
1266	      {
1267	        size_t dynamic_multiplier =
1268	            static_cast<size_t>(compute_cycles % weight_multiplier_) + 1;
1269	        size *= dynamic_multiplier;
1270	      }
1271	
1272	      if (!unified_buffer_manager_->AreDataTypeReady(type, size))
1273	      {
1274	        missing_types.push_back(type);
1275	      }
1276	    }
1277	
1278	    // 只有恰好只有一个数据类型缺失时才统计
1279	    if (missing_types.size() == 1)
1280	    {
1281	      DataType missing_type = missing_types[0];
1282	      data_wait_stats_[missing_type]++;
1283	      total_wait_cycles_++;
1284	
1285	      return;
1286	    }
1287	
1288	    // 如果没有缺失或有多个缺失，不统计但需要处理
1289	    if (!missing_types.empty())
1290	    {
1291	      return;
1292	    }
1293	
1294	    // 所有数据都准备好了，开始计算。
1295	    // 统一补偿 1 个调度/相位周期，避免不同 transport 模式下对小粒度计算不公平。
1296	    int latency = task_manager_->get_compute_latency();
1297	    latency = std::max(latency - 1, 0);
1298	    if (latency <= 0)
1299	    {
1300	      is_compute_complete = true;
1301	      return;
1302	    }
1303	    consume_cycles_left = latency;
1304	    compute_in_progress_ = true;
1305	    started_this_cycle = true;
1306	  }
1307	
1308	  if (compute_in_progress_)
1309	  {
1310	    if (started_this_cycle)
1311	    {
1312	      return;
1313	    }
1314	
1315	    consume_cycles_left--;
1316	    assert(consume_cycles_left >= 0 && "Consume cycles underflow");
1317	
1318	    if (consume_cycles_left == 0)
1319	    {
1320	      compute_in_progress_ = false;
1321	      is_compute_complete = true;
1322	    }
1323	  }
1324	}
