1343	// 计算从当前层到目标层之间的实际目标数量
1344	int ProcessingElement::calculate_target_count(int current_level,
1345	                                              DataType data_type,
1346	                                              PE_Role target_role)
1347	{
1348	  int target_count = 1;
1349	
1350	  // 从当前层开始，遍历到目标层之前
1351	  for (int level = current_level;; level++)
1352	  {
1353	    const LevelConfig &level_config =
1354	        GlobalParams::hierarchical_config.get_level_config(level);
1355	
1356	    // 检查是否到达目标层
1357	    if (level_config.roles == target_role)
1358	    {
1359	      break; // 到达目标层，停止累乘
1360	    }
1361	
1362	    // 检查该层是否有路由模式配置
1363	    if (level_config.has_routing_patterns)
1364	    {
1365	      auto it = level_config.routing_patterns.find(data_type);
1366	      if (it != level_config.routing_patterns.end())
1367	      {
1368	        // 累乘该数据类型的port_groups数量
1369	        target_count *= it->second.port_groups.size();
1370	      }
1371	    }
1372	  }
1373	
1374	  return target_count;
1375	}
