1377	int ProcessingElement::get_target_bandwidth(int current_level,
1378	                                            PE_Role target_role)
1379	{
1380	  int bandwidth =
1381	      GlobalParams::hierarchical_config.get_level_config(current_level)
1382	          .bandwidth;
1383	
1384	  // 从当前层开始，遍历到目标层之前
1385	  for (int level = current_level + 1;; level++)
1386	  {
1387	    const LevelConfig &level_config =
1388	        GlobalParams::hierarchical_config.get_level_config(level);
1389	
1390	    // 检查是否到达目标层
1391	    if (level_config.roles == target_role)
1392	    {
1393	      break; // 到达目标层，停止累乘
1394	    }
1395	
1396	    bandwidth = std::min(bandwidth, level_config.bandwidth);
1397	  }
1398	
1399	  return bandwidth;
1400	}
