1402	// in PE.cpp
1403	void ProcessingElement::run_storage_logic()
1404	{
1405	  if (role != ROLE_GLB && role != ROLE_DRAM)
1406	  {
1407	    return;
1408	  }
1409	
1410	  if (logical_timestamp >= task_manager_->get_total_timesteps())
1411	  {
1412	    all_transfer_tasks_finished = true;
1413	    return;
1414	  }
1415	
1416	  if (!dispatch_in_progress_)
1417	  {
1418	    std::map<DataType, size_t> data_map =
1419	        task_manager_->get_working_set_for_role(role_to_str(role))
1420	            ->get_data_map();
1421	    for (const auto &entry : data_map)
1422	    {
1423	      if (entry.first != DataType::OUTPUT)
1424	      {
1425	        if (!unified_buffer_manager_->AreDataTypeReady(entry.first,
1426	                                                       entry.second))
1427	          return;
1428	      }
1429	      else
1430	      {
1431	        if (!unified_buffer_manager_->AreDataTypeReady(entry.first,
1432	                                                       entry.second))
1433	          return;
1434	      }
1435	    }
1436	
1437	    current_dispatch_task_ =
1438	        task_manager_->get_task_for_timestep(logical_timestamp);
1439	    LOG << "PE[" << local_id << "] Starting dispatch for timestep "
1440	        << logical_timestamp << " with "
1441	        << current_dispatch_task_.sub_tasks.size() << " subtasks." << endl;
1442	    command_to_send = get_command_to_send();
1443	
1444	    dispatch_in_progress_ = true;
1445	  }
1446	
1447	  if (current_dispatch_task_.sub_tasks.empty())
1448	  {
1449	    return;
1450	  }
1451	
1452	  // --- 1. [核心] 从待办列表中随机选择一个子任务 ---
1453	  int num_pending_subtasks = current_dispatch_task_.sub_tasks.size();
1454	  auto it = current_dispatch_task_.sub_tasks.begin();
1455	
1456	  while (it != current_dispatch_task_.sub_tasks.end())
1457	  {
1458	    DataDispatchInfo &selected_task = *it;
1459	    // 计算此数据类型对应的VC ID
1460	    int vc_id = get_vc_id_for_packet_by_task(selected_task);
1461	
1462	    // 检查对应的VC队列是否为空（实现"size只为1"的规则）
1463	    if (!packet_queues_[vc_id].empty())
1464	    {
1465	      ++it;
1466	      continue; // 该VC通道忙，跳过
1467	    }
1468	
1469	    LOG << "PE[" << local_id << "] Generating packet for task: "
1470	        << "Type=" << DataType_to_str(selected_task.type)
1471	        << ", Size=" << selected_task.size << endl;
1472	
1473	    Packet pkt;
1474	    pkt.src_id = local_id;
1475	    pkt.dst_id = -2;
1476	    pkt.target_role = selected_task.target_role;
1477	
1478	    // 计算实际的目标数量
1479	    int target_count = calculate_target_count(level_index, selected_task.type,
1480	                                              selected_task.target_role);
1481	
1482	    int bandwidth_scale =
1483	        GlobalParams::hierarchical_config.get_level_config(level_index)
1484	            .bandwidth /
1485	        GlobalParams::word_bits;
1486	    pkt.vc_id = vc_id; // 使用预先计算的VC ID
1487	    pkt.payload_data_size = selected_task.size;
1488	    pkt.logical_timestamp = logical_timestamp;
1489	    pkt.data_type = selected_task.type;
1490	
1491	    if (target_count > 1)
1492	    {
1493	      // 多目标场景：使用当前层实际带宽
1494	      int current_bandwidth =
1495	          GlobalParams::hierarchical_config.get_level_config(level_index)
1496	              .bandwidth;
1497	
1498	      // Transmission mode switching logic for packet size calculation
1499	      if (GlobalParams::transmission_mode == "traditional")
1500	      {
1501	        // 获取目标层带宽
1502	        int target_bandwidth =
1503	            get_target_bandwidth(level_index, selected_task.target_role);
1504	        // 获取当前层带宽
1505	        int current_level_bandwidth =
1506	            GlobalParams::hierarchical_config.get_level_config(level_index)
1507	                .bandwidth;
1508	        // 获取当前层的 bank_count
1509	        int bank_count =
1510	            GlobalParams::hierarchical_config.get_level_config(level_index)
1511	                .bank_count;
1512	
1513	        // 计算并行度：受限于带宽比和 bank 数量
1514	        int bandwidth_ratio = current_level_bandwidth / target_bandwidth;
1515	        int parallel_degree =
1516	            std::max(1, std::min(bandwidth_ratio, bank_count));
1517	
1518	        // Traditional mode: 基于并行度调整 flit 数
1519	        int bandwidth_scale = target_bandwidth / GlobalParams::word_bits;
1520	        int single_packet_size =
1521	            (selected_task.size + bandwidth_scale - 1) / bandwidth_scale;
1522	        int total_flits = target_count * single_packet_size;
1523	        pkt.size = pkt.flit_left =
1524	            2 + (total_flits + parallel_degree - 1) / parallel_degree;
1525	      }
1526	      else
1527	      {
1528	        // Optimized mode: hierarchical slicing based on bandwidth overflow
1529	
1530	        // 步骤A：计算单层切片是否溢出
1531	        double R = (double)(target_count * 8) / current_bandwidth;
1532	
1533	        // 步骤B：确定单层Flit数（向上取整）
1534	        int Nslice;
1535	        if (R <= 1.0)
1536	        {
1537	          Nslice = 1;
1538	        }
1539	        else
1540	        {
1541	          Nslice = (int)ceil(R);
1542	        }
1543	
1544	        // 步骤C：计算总长度
1545	        pkt.size = pkt.flit_left = Nslice * selected_task.size + 2;
1546	      }
1547	    }
1548	    else
1549	    {
1550	      // 单目标场景：保持原有计算
1551	      pkt.size = pkt.flit_left =
1552	          (selected_task.size + bandwidth_scale - 1) / bandwidth_scale + 2;
1553	    }
1554	    pkt.command = command_to_send;
1555	
1556	    // 将Packet推入对应的VC队列
1557	    packet_queues_[vc_id].push(pkt);
1558	    it = current_dispatch_task_.sub_tasks.erase(it);
1559	  }
1560	}
1561	
1562	int ProcessingElement::get_command_to_send() // tofix
1563	                                             // 当完整模拟时需要通过获取子
1564	{
1565	  PE_Role nextRole = static_cast<PE_Role>(static_cast<int>(role) + 1);
1566	  auto commands = task_manager_->get_commands_for_role(role_to_str(nextRole));
1567	  if (commands == nullptr || commands->empty())
1568	  {
1569	    dbg(sc_time_stamp(), name(),
1570	        "[CMD_ERROR] No command definitions found for downstream role: " +
1571	            role_to_str(nextRole));
1572	    assert(false && "cannot find available command");
1573	    return -2; // 返回无效命令
1574	  }
1575	
1576	  if (logical_timestamp + 1 >= task_manager_->get_total_timesteps())
1577	  {
1578	    return commands->size() + 1;
1579	  }
1580	
1581	  // if (role == ROLE_GLB &&
1582	  //     logical_timestamp + 1 >= task_manager_->get_total_timesteps() &&
1583	  //     task_manager_->get_command_definition(pending_commands_.begin()->second)
1584	  //             .weights > task_manager_->get_current_working_set().weights) {
1585	  //   return commands->size() + 1;
1586	  // }
1587	  DataDelta next_delta;
1588	  DispatchTask next_task = task_manager_->get_task_for_timestep(
1589	      (logical_timestamp + 1) % task_manager_->get_total_timesteps());
1590	  // 这条命令需要在负载下被测试
1591	
1592	  for (const DataDispatchInfo &sub_task : next_task.sub_tasks)
1593	  {
1594	    // 不再使用 target_ids，multicast_factor 设为 1
1595	    int multicast_factor = 1;
1596	    if (sub_task.type == DataType::WEIGHT)
1597	      next_delta.weights += sub_task.size * multicast_factor;
1598	    if (sub_task.type == DataType::INPUT)
1599	      next_delta.inputs += sub_task.size * multicast_factor;
1600	    if (sub_task.type == DataType::OUTPUT)
1601	      next_delta.outputs += sub_task.size * multicast_factor;
1602	  }
1603	
1604	  for (const auto &cmd : *commands)
1605	  {
1606	    // 比较推算出的 payload 和命令中定义的 payload
1607	    if (cmd.evict_payload.inputs == next_delta.inputs &&
1608	        cmd.evict_payload.outputs == next_delta.outputs)
1609	    {
1610	      return cmd.command_id;
1611	    }
1612	  }
1613	  if (commands->size() == 1)
1614	    return commands->front().command_id;
1615	
1616	  assert(false && "cannot find available command");
1617	  return -2;
1618	}
1619	Flit ProcessingElement::generate_next_flit_from_queue(
1620	    std::queue<Packet> &queue)
1621	{
1622	  Flit flit;
1623	  Packet packet = queue.front();
1624	
1625	  // 填充公共字段
1626	  flit.src_id = packet.src_id;
1627	  flit.vc_id = packet.vc_id;
1628	  flit.logical_timestamp = packet.logical_timestamp;
1629	  flit.sequence_no = packet.size - packet.flit_left;
1630	  flit.sequence_length = packet.size;
1631	  flit.hop_no = 0;
1632	  flit.payload_data_size = packet.payload_data_size;
1633	  flit.hub_relay_node = NOT_VALID;
1634	  flit.data_type = packet.data_type;
1635	  flit.command = packet.command;
1636	
1637	  flit.target_role = packet.target_role;
1638	
1639	  // 确定flit类型
1640	  if (packet.size == packet.flit_left)
1641	  {
1642	    flit.flit_type = FLIT_TYPE_HEAD;
1643	    std::copy(std::begin(packet.payload_sizes), std::end(packet.payload_sizes),
1644	              flit.payload_sizes);
1645	  }
1646	  else if (packet.flit_left == 1)
1647	  {
1648	    flit.flit_type = FLIT_TYPE_TAIL;
1649	  }
1650	  else
1651	  {
1652	    flit.flit_type = FLIT_TYPE_BODY;
1653	  }
1654	
1655	  // 处理flit_left和队列pop
1656	  queue.front().flit_left--;
1657	  if (queue.front().flit_left == 0)
1658	  {
1659	    queue.pop();
1660	  }
1661	
1662	  return flit;
1663	}
1664	
1665	unsigned int ProcessingElement::getQueueSize() const
1666	{
1667	  return packet_queues_.size();
1668	}
1669	void ProcessingElement::evict_weights_self()
1670	{
1671	  size_t current_weights =
1672	      unified_buffer_manager_->GetCurrentSize(DataType::WEIGHT);
1673	
1674	  if (current_weights > 0)
1675	  {
1676	    size_t evict_amount = std::min(weight_eviction_amount_, current_weights);
1677	    unified_buffer_manager_->RemoveData(DataType::WEIGHT, evict_amount);
1678	
1679	    LOG << "[SELF_EVICT] Evicted " << evict_amount
1680	        << " weights at compute cycle " << compute_cycles << ", remaining: "
1681	        << unified_buffer_manager_->GetCurrentSize(DataType::WEIGHT) << endl;
1682	
1683	    buffer_state_changed_event.notify(SC_ZERO_TIME);
1684	  }
1685	}
